import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), k = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Integer[] ids = new Integer[n];
        for (int i = 0; i < n; i++) ids[i] = i;
        // value desc, then earliest index first
        Arrays.sort(ids, (x, y) -> a[x] != a[y] ? Long.compare(a[y], a[x]) : Integer.compare(x, y));
        int[] chosen = new int[k];
        for (int i = 0; i < k; i++) chosen[i] = ids[i];
        Arrays.sort(chosen); // restore original order
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < k; i++) {
            if (i > 0) out.append(' ');
            out.append(a[chosen[i]]);
        }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"sort"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := int(nextInt()), int(nextInt())
	a := make([]int64, n)
	ids := make([]int, n)
	for i := range a {
		a[i] = nextInt()
		ids[i] = i
	}
	// value desc, then earliest index first
	sort.Slice(ids, func(i, j int) bool {
		x, y := ids[i], ids[j]
		if a[x] != a[y] {
			return a[x] > a[y]
		}
		return x < y
	})
	chosen := ids[:k]
	sort.Ints(chosen) // restore original order
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i, id := range chosen {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatInt(a[id], 10))
	}
	w.WriteByte('\n')
}
